package org.khtml

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertIs
import kotlin.test.assertTrue

class TokenizerTest {

    @Test
    fun `empty input should be ignored`() {
        val tok = Tokenizer()
        val got = tok.tokenize("")
        assertTrue(got.isEmpty())
    }

    @Test
    fun `spaces should be emitted as plain text containing white-space`() {
        val tok = Tokenizer()
        val got = tok.tokenize("  \n\t ")
        val token = got[0]
        val expected = HtmlToken.Text(
            content = "  \n\t ",
            position = SourcePosition(1, 1)
        )
        assertIs<HtmlToken.Text>(token)
        assertEquals(expected, token)
    }

    @Test
    fun `consume an open tag and emit OpenTag`() {
        val tok = Tokenizer()
        val got = tok.tokenize("<p>")
        val token = got[0]
        val expected = HtmlToken.TagOpen(
            name = "p",
            position = SourcePosition(1, 2)
        )
        assertIs<HtmlToken.TagOpen>(token)
        assertTrue(token.attributes.isEmpty())
        assertEquals(expected, token)
    }

    @Test
    fun `return open tag for a valid html tag that appends a new line`() {
        val tok = Tokenizer()
        val got = tok.tokenize("<p>\n")
        assertFalse(got.isEmpty())
        val token0 = got[0]
        val expectedTag = HtmlToken.TagOpen(
            name = "p",
            position = SourcePosition(1, 2)
        )
        assertIs<HtmlToken.TagOpen>(token0)
        assertEquals(expectedTag, token0)

        val token1 = got[1]
        val expectedText = HtmlToken.Text(
            content = "\n",
            position = SourcePosition(1, 4)
        )
        assertIs<HtmlToken.Text>(token1)
        assertEquals(expectedText, token1)
    }

    @Test
    fun `parse tag with attributes`() {
        val tok = Tokenizer()
        val got = tok.tokenize("""<a href="https://example.com" target="_blank">""")
        assertEquals(1, got.size)

        val token = got[0]
        assertIs<HtmlToken.TagOpen>(token)
        assertEquals("a", token.name)
        assertEquals("https://example.com", token.attributes["href"])
        assertEquals("_blank", token.attributes["target"])
    }

    @Test
    fun `parse closing tag`() {
        val tok = Tokenizer()
        val got = tok.tokenize("</p>")
        assertEquals(1, got.size)

        val token = got[0]
        assertIs<HtmlToken.TagClose>(token)
        assertEquals("p", token.name)
    }

    @Test
    fun `parse full element with text inside`() {
        val tok = Tokenizer()
        val got = tok.tokenize("<p>Hello World</p>")
        assertEquals(3, got.size)

        val openTag = got[0]
        assertIs<HtmlToken.TagOpen>(openTag)
        assertEquals("p", openTag.name)

        val text = got[1]
        assertIs<HtmlToken.Text>(text)
        assertEquals("Hello World", text.content)

        val closeTag = got[2]
        assertIs<HtmlToken.TagClose>(closeTag)
        assertEquals("p", closeTag.name)
    }

    @Test
    fun `stray less than symbol should be consumed as text`() {
        val tok = Tokenizer()
        val got = tok.tokenize("if x < 5 then true")
        assertEquals(1, got.size)

        val text = got[0]
        assertIs<HtmlToken.Text>(text)
        assertEquals("if x < 5 then true", text.content)
    }

    @Test
    fun `unclosed tag at EOF should be emitted as text`() {
        val tok = Tokenizer()
        val got = tok.tokenize("<p unclosed")
        assertEquals(1, got.size)

        val text = got[0]
        assertIs<HtmlToken.Text>(text)
        assertEquals("<p unclosed", text.content)
    }
}
